using System;using System.IO;using System.Collections.Generic;using System.Web.Script.Serialization;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Runtime;
public class SupplierInventory{
[CommandMethod("AIDESUPPLIERINVENTORY")]public void Run(){var db=Autodesk.AutoCAD.ApplicationServices.Application.DocumentManager.MdiActiveDocument.Database;var rows=new List<object>();using(var tx=db.TransactionManager.StartTransaction()){var bt=(BlockTable)tx.GetObject(db.BlockTableId,OpenMode.ForRead);var ms=(BlockTableRecord)tx.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForRead);foreach(ObjectId id in ms){var br=tx.GetObject(id,OpenMode.ForRead) as BlockReference;if(br==null)continue;var attrs=new Dictionary<string,string>();foreach(ObjectId aid in br.AttributeCollection){var a=(AttributeReference)tx.GetObject(aid,OpenMode.ForRead);attrs[a.Tag]=a.TextString;}var props=new Dictionary<string,object>();if(br.IsDynamicBlock)foreach(DynamicBlockReferenceProperty p in br.DynamicBlockReferencePropertyCollection)props[p.PropertyName]=new{value=p.Value,allowed=p.GetAllowedValues()};rows.Add(new{handle=br.Handle.ToString(),attributes=attrs,properties=props,x=br.Position.X,y=br.Position.Y});}}var serializer=new JavaScriptSerializer();serializer.MaxJsonLength=int.MaxValue;File.WriteAllText(Environment.GetEnvironmentVariable("AIDE_INVENTORY_OUTPUT"),serializer.Serialize(rows));}}
